using System;using System.IO;using System.Runtime.InteropServices;using System.Text;
[assembly:System.Reflection.AssemblyFileVersion("0.1.0.29")]
static class ClassicBluetoothStatus {
 [StructLayout(LayoutKind.Sequential)]struct Search {public uint Size;[MarshalAs(UnmanagedType.Bool)]public bool Authenticated;[MarshalAs(UnmanagedType.Bool)]public bool Remembered;[MarshalAs(UnmanagedType.Bool)]public bool Unknown;[MarshalAs(UnmanagedType.Bool)]public bool Connected;[MarshalAs(UnmanagedType.Bool)]public bool Inquiry;public byte Timeout;public IntPtr Radio;}
 [StructLayout(LayoutKind.Sequential)]struct Time {public ushort Y,M,Dow,D,H,Min,S,Ms;}
 [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)]struct Device {public uint Size;public ulong Address;public uint Class;[MarshalAs(UnmanagedType.Bool)]public bool Connected;[MarshalAs(UnmanagedType.Bool)]public bool Remembered;[MarshalAs(UnmanagedType.Bool)]public bool Authenticated;public Time LastSeen,LastUsed;[MarshalAs(UnmanagedType.ByValTStr,SizeConst=248)]public string Name;}
 [DllImport("bthprops.cpl",SetLastError=true)]static extern IntPtr BluetoothFindFirstDevice(ref Search search,ref Device device);
 [DllImport("bthprops.cpl",SetLastError=true)][return:MarshalAs(UnmanagedType.Bool)]static extern bool BluetoothFindNextDevice(IntPtr find,ref Device device);
 [DllImport("bthprops.cpl")][return:MarshalAs(UnmanagedType.Bool)]static extern bool BluetoothFindDeviceClose(IntPtr find);
 [DllImport("bthprops.cpl")]static extern uint BluetoothEnumerateInstalledServices(IntPtr radio,ref Device device,ref uint count,[Out]Guid[] services);
 static int Main(){var result=new StringBuilder();var search=new Search{Size=(uint)Marshal.SizeOf(typeof(Search)),Authenticated=true,Remembered=true,Connected=true,Inquiry=false};var device=new Device{Size=(uint)Marshal.SizeOf(typeof(Device))};IntPtr find=BluetoothFindFirstDevice(ref search,ref device);try{result.AppendLine("SearchSize="+search.Size+";DeviceSize="+device.Size);if(find==IntPtr.Zero){result.AppendLine("EnumerationError="+Marshal.GetLastWin32Error());return 1;}int count=0;do{count++;result.AppendLine("Name="+device.Name+";Connected="+device.Connected+";Remembered="+device.Remembered+";Authenticated="+device.Authenticated+";Class="+device.Class.ToString("X"));uint serviceCount=64;var services=new Guid[64];uint serviceResult=BluetoothEnumerateInstalledServices(IntPtr.Zero,ref device,ref serviceCount,services);result.AppendLine("ServicesResult="+serviceResult+";Count="+serviceCount);if(serviceResult==0)for(int i=0;i<serviceCount;i++)result.AppendLine("InstalledService="+services[i]);device.Size=(uint)Marshal.SizeOf(typeof(Device));}while(BluetoothFindNextDevice(find,ref device));result.AppendLine("ClassicDevices="+count+";ReadOnly=True");return 0;}finally{if(find!=IntPtr.Zero)BluetoothFindDeviceClose(find);File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"classic-bluetooth-status.local.txt"),result.ToString());}}
}